  "inlineSchema": "// KAVANA — Single-Vendor Ecommerce Demo (Portfolio)\n// Prisma schema with SQLite\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  // Custom output: path khusus agar dev-server yang sudah berjalan bisa\n  // memuat ulang client hasil generate terbaru (modul baru = cache miss).\n  output   = \"../prisma/generated-client\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  name      String\n  password  String // scrypt hash \"salt:hash\"\n  role      String   @default(\"CUSTOMER\") // CUSTOMER | ADMIN\n  phone     String?\n  address   String?\n  city      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sessions    Session[]\n  orders      Order[]\n  reviews     Review[]\n  resetTokens PasswordResetToken[]\n}\n\nmodel Session {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\n/// Mock password-reset tokens (demo: kode 6 digit dikirim \"via email\",\n/// di sandbox kode ditampilkan langsung di UI mode demo).\nmodel PasswordResetToken {\n  id        String    @id @default(cuid())\n  code      String    @unique // 6 digit\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n}\n\nmodel Category {\n  id       String    @id @default(cuid())\n  name     String    @unique\n  slug     String    @unique\n  icon     String? // lucide icon name hint for frontend\n  products Product[]\n}\n\nmodel Product {\n  id             String      @id @default(cuid())\n  name           String\n  slug           String      @unique\n  description    String\n  price          Float\n  compareAtPrice Float? // harga sebelum diskon (harga coret); null = tidak didiskon\n  stock          Int\n  images         String // JSON string array of image urls\n  featured       Boolean     @default(false)\n  isActive       Boolean     @default(true)\n  categoryId     String\n  category       Category    @relation(fields: [categoryId], references: [id])\n  orderItems     OrderItem[]\n  reviews        Review[]\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n\n  @@index([categoryId])\n  @@index([featured])\n}\n\nmodel Order {\n  id            String      @id @default(cuid())\n  orderNumber   String      @unique\n  userId        String\n  user          User        @relation(fields: [userId], references: [id])\n  status        String      @default(\"PENDING\") // PENDING | PAID | SHIPPED | COMPLETED | CANCELLED\n  customerName  String\n  phone         String\n  address       String\n  city          String\n  postalCode    String?\n  notes         String?\n  subtotal      Float\n  shippingCost  Float\n  discount      Float       @default(0) // potongan dari kode promo\n  promoCode     String? // kode voucher yang dipakai (mis. KAVANA10)\n  total         Float\n  paymentMethod String? // VA_BCA | VA_MANDIRI | EWALLET | CARD (mock)\n  paymentRef    String? // mock payment reference e.g. PAY-xxxx\n  paidAt        DateTime?\n  items         OrderItem[]\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel OrderItem {\n  id        String  @id @default(cuid())\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n  name      String // snapshot of product name at purchase time\n  price     Float // snapshot of price at purchase time\n  image     String? // snapshot\n  quantity  Int\n\n  @@index([orderId])\n  @@index([productId])\n}\n\nmodel Review {\n  id           String   @id @default(cuid())\n  userId       String\n  user         User     @relation(fields: [userId], references: [id])\n  productId    String\n  product      Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  rating       Int // 1..5\n  comment      String\n  helpfulCount Int      @default(0) // jumlah \"Membantu\" dari pengguna lain\n  createdAt    DateTime @default(now())\n\n  @@unique([userId, productId])\n  @@index([productId])\n}\n\n/// Outbox email mock (demo): setiap event penting (reset password, welcome,\n/// pesanan dibayar/dikirim/dibatalkan) mencatat \"email terkirim\" di sini.\n/// Di produksi tabel ini diganti antrean pengiriman email sungguhan (SMTP).\nmodel EmailLog {\n  id          String    @id @default(cuid())\n  toEmail     String\n  subject     String\n  body        String\n  type        String // PASSWORD_RESET | WELCOME | ORDER_PAID | ORDER_SHIPPED | ORDER_CANCELLED\n  orderId     String?\n  orderNumber String?\n  readAt      DateTime?\n  createdAt   DateTime  @default(now())\n\n  @@index([type])\n  @@index([readAt])\n  @@index([createdAt])\n}\n",
